/**
 * Compact static OpenType/TrueType subsets derived from commercial-friendly SIL Open Font License 1.1 fonts.
 * Derivative subset internal font names are renamed to WBR Ritual * Subset per SIL OFL 1.1 Clause 3.
 * Full copyright & license texts live in `packages/scene-runtime/licenses/fonts/`.
 */

export type RitualFontId =
  | "mashanZheng"
  | "lxgwZhenKai"
  | "yujiSyuku"
  | "cinzelBold"
  | "ebGaramondSemiBold"
  | "frankRuhlBold"
  | "kleeOneSemiBold";

export const RITUAL_FONT_SUBSETS_B64: Record<RitualFontId, { base64: string; source: string; licenseFile: string }> = {
  mashanZheng: {
    source: "Ma Shan Zheng (SIL OFL 1.1)",
    licenseFile: "MaShanZheng-OFL.txt",
    base64: "",
  },
  lxgwZhenKai: {
    source: "LXGW ZhenKai GB (SIL OFL 1.1)",
    licenseFile: "LXGWZhenKaiGB-OFL.txt",
    base64: "",
  },
  yujiSyuku: {
    source: "Yuji Syuku (SIL OFL 1.1)",
    licenseFile: "YujiSyuku-OFL.txt",
    base64: "",
  },
  cinzelBold: {
    source: "Cinzel Bold wght=700 (SIL OFL 1.1)",
    licenseFile: "Cinzel-OFL.txt",
    base64: "",
  },
  ebGaramondSemiBold: {
    source: "EB Garamond SemiBold wght=650 (SIL OFL 1.1)",
    licenseFile: "EBGaramond-OFL.txt",
    base64: "",
  },
  frankRuhlBold: {
    source: "Frank Ruhl Libre Bold wght=700 (SIL OFL 1.1)",
    licenseFile: "FrankRuhlLibre-OFL.txt",
    base64: "",
  },
  kleeOneSemiBold: {
    source: "Klee One SemiBold (SIL OFL 1.1)",
    licenseFile: "KleeOne-OFL.txt",
    base64: "",
  },
};

export function decodeFontSubsetBuffer(id: RitualFontId): ArrayBuffer {
  const b64 = RITUAL_FONT_SUBSETS_B64[id].base64;
  if (typeof Buffer !== "undefined") {
    const buf = Buffer.from(b64, "base64");
    return buf.buffer.slice(buf.byteOffset, buf.byteOffset + buf.byteLength);
  }
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes.buffer;
}
